function excelSerialToDate(n) {
  const epoch = new Date(Date.UTC(1899, 11, 30));
  return new Date(epoch.getTime() + Number(n) * 86400000);
}

function normalizeExcelDate(value) {
  if (value === null || value === undefined || value === '') return null;
  if (!isNaN(value)) {
    const d = excelSerialToDate(value);
    const day = String(d.getUTCDate()).padStart(2, '0');
    const month = String(d.getUTCMonth() + 1).padStart(2, '0');
    return `${day}/${month}/${d.getUTCFullYear()}`;
  }
  return value;
}

// Extract from File1 is now headerRow=false: each top row = [label, value, ...].
// read positionally via Object.values (tolerant of {A,B} vs {row:[..]} shapes).
function rowCells(json) {
  const vals = Object.values(json);
  if (vals.length === 1 && Array.isArray(vals[0])) return vals[0];
  return vals;
}

function findLabeledValue(labelRegex) {
  const rows = $('Extract from File1').all();
  for (const r of rows) {
    const vals = rowCells(r.json);
    if (vals.length < 2) continue;
    const label = String(vals[0] ?? '').trim();
    if (labelRegex.test(label)) return vals[1];
  }
  return null;
}

function parseToDate(value) {
  if (value === null || value === undefined || value === '') return null;
  if (!isNaN(value)) return excelSerialToDate(value);
  const m = String(value).trim().match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
  if (!m) return null;
  let a = Number(m[1]), b = Number(m[2]); let y = m[3];
  if (y.length === 2) y = '20' + y;
  let day, month;
  if (a > 12 && b <= 12)      { day = a; month = b; }
  else if (b > 12 && a <= 12) { day = b; month = a; }
  else                        { day = a; month = b; }
  return new Date(Date.UTC(Number(y), month - 1, day));
}

// LOADING (shipment) date: real date cell -> excel serial -> exact date;
// text date cell -> year-width + >12 rule + ETD-proximity fallback
function resolveShipmentDate() {
  const v = findLabeledValue(/^LOADING/i);
  if (v === null || v === undefined || v === '') return null;
  if (!isNaN(v)) return normalizeExcelDate(Number(v)); // date serial -> exact

  const m = String(v).trim().match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
  if (!m) return null;
  let a = Number(m[1]), b = Number(m[2]); const yy = m[3];
  const y = yy.length === 2 ? '20' + yy : yy;
  const fmt = (d, mo) => `${String(d).padStart(2,'0')}/${String(mo).padStart(2,'0')}/${y}`;
  if (yy.length === 2) { if (a > 12 && b <= 12) return fmt(a, b); return fmt(b, a); }
  if (a > 12 && b <= 12) return fmt(a, b);
  if (b > 12 && a <= 12) return fmt(b, a);
