  if (etd) {
    const candAB = new Date(Date.UTC(Number(y), b - 1, a));
    const candBA = new Date(Date.UTC(Number(y), a - 1, b));
    return Math.abs(candBA - etd) < Math.abs(candAB - etd) ? fmt(b, a) : fmt(a, b);
  }
  return fmt(a, b);
}

